    import {addFile, getTree, pushTree, removeFile} from "../frontend/api.js"

    const listStyles = `
.files-list {
    display: grid;
    width: 100%;
    max-width: 760px;
    gap: 6px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.files-list-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 8px 12px;
    border: 1px solid rgba(127, 127, 127, 0.35);
    border-radius: 3px;
}

.files-list-name {
    overflow: hidden;
    font: 14px/1.4 ui-monospace, SFMono-Regular, Consolas, monospace;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.files-list-remove {
    flex: 0 0 auto;
    min-width: 0;
    min-height: 34px;
    margin: 0;
    padding: 0 12px;
    border-color: rgba(255, 138, 128, 0.35);
    color: #ffd9d4;
    background: rgba(70, 32, 28, 0.6);
    font-size: 13px;
}

.files-list-remove:hover,
.files-list-remove:focus-visible {
    border-color: rgba(255, 122, 107, 0.7);
    color: #ffffff;
}

.files-list-empty {
    padding: 16px 12px;
    border: 1px solid rgba(127, 127, 127, 0.3);
    border-radius: 3px;
    font-size: 14px;
    text-align: center;
}
`

    const injectStyles = () => {
        if (document.getElementById("evenbetterfiles-styles")) return
        const style = document.createElement("style")
        style.id = "evenbetterfiles-styles"
        style.textContent = listStyles
        document.head.appendChild(style)
    }

    export default function EvenBetterFiles(van) {
        injectStyles()
        const {button, div, form, h2, input, label, li, p, span, textarea, ul} = van.tags
        const tree = van.state(null)
        const pendingChanges = van.state(0)
        const busy = van.state(false)
        const status = van.state("Loading files...")

        const refresh = async () => {
            busy.val = true
            status.val = "Loading files..."
            try {
                const result = await getTree()
                tree.val = result.tree
                pendingChanges.val = result.pendingChanges ?? 0
                status.val = `Loaded ${result.repo}.`
            } catch (error) {
                status.val = error.message
            } finally {
                busy.val = false
            }
        }

        const save = async () => {
            if (busy.val || pendingChanges.val === 0) return
            busy.val = true
            status.val = "Saving to GitHub..."
            try {
                const result = await pushTree("Update files from EvenBetterFiles")
                tree.val = result.tree
                pendingChanges.val = result.pendingChanges ?? 0
                status.val = result.message
            } catch (error) {
                status.val = error.message
            } finally {
                busy.val = false
            }
        }

        const addFileFromForm = async event => {
            event.preventDefault()
            if (busy.val) return
            const formData = new FormData(event.currentTarget)
            const path = formData.get("path")?.toString().trim() ?? ""
            const content = formData.get("content")?.toString() ?? ""
            if (!path) return
            busy.val = true
            status.val = "Adding file..."
            try {
                const result = await addFile(path, content)
                tree.val = result.tree
                pendingChanges.val = result.pendingChanges ?? 0
                status.val = `Added ${path}. Save to keep it.`
                event.currentTarget.reset()
            } catch (error) {
                status.val = error.message
            } finally {
                busy.val = false
            }
        }

        const removePath = async targetPath => {
            if (busy.val) return
            busy.val = true
            status.val = `Removing ${targetPath}...`
            try {
                const result = await removeFile(targetPath)
                tree.val = result.tree
                pendingChanges.val = result.pendingChanges ?? 0
                status.val = `Removed ${targetPath}. Save to keep it.`
            } catch (error) {
                status.val = error.message
            } finally {
                busy.val = false
            }
        }

        const collectFiles = (node, prefix = "") => {
            const files = []
            for (const [name, child] of Object.entries(node.children ?? {})) {
                const childPath = prefix ? `${prefix}/${name}` : name
                if (child.type === "directory") {
                    files.push(...collectFiles(child, childPath))
                } else {
                    files.push({path: childPath, size: child.size ?? 0})
                }
            }
            return files
        }

        const fileList = () => {
            const files = tree.val ? collectFiles(tree.val.root) : []
            return ul({class: "files-list"},
                files.length
                    ? files.map(file => li({class: "files-list-item"},
                        span({class: "files-list-name"}, file.path),
                        button({
                            type: "button",
                            class: "files-list-remove",
                            onclick: () => removePath(file.path),
                            "aria-label": `Remove ${file.path}`,
                        }, "Remove"),
                    ))
                    : li({class: "files-list-empty"}, tree.val ? "No files yet." : "Loading files..."),
            )
        }

        const app = div({class: "files-app", "aria-busy": () => String(busy.val)},
            h2("EvenBetterFiles"),
            div({class: "files-toolbar"},
                button({type: "button", onclick: refresh, disabled: () => busy.val}, "Refresh"),
                button({
                    type: "button",
                    onclick: save,
                    disabled: () => busy.val || pendingChanges.val === 0,
                }, () => `Save (${pendingChanges.val})`),
            ),
            form({class: "files-operation-form", onsubmit: addFileFromForm},
                label({for: "evenbetterfiles-path"}, "File path"),
                input({
                    id: "evenbetterfiles-path",
                    name: "path",
                    type: "text",
                    placeholder: "folder/file.txt",
                    autocomplete: "off",
                    required: true,
                }),
                label({for: "evenbetterfiles-content"}, "Contents"),
                textarea({
                    id: "evenbetterfiles-content",
                    name: "content",
                    placeholder: "Enter UTF-8 text",
                    required: true,
                }),
                button({type: "submit", disabled: () => busy.val}, "Add file"),
            ),
            () => fileList(),
            p({class: "files-status", role: "status", "aria-live": "polite"}, () => status.val),
        )

        refresh()
        return app
    }
